import{_ as p,r as a,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"集合（Collection） - October CMS - 3.x","titleTemplate":false,"description":"向页面添加模型记录集合。","frontmatter":{"subtitle":"向页面添加模型记录集合。"},"headers":[{"level":2,"title":"可用属性","slug":"可用属性","link":"#可用属性","children":[]},{"level":2,"title":"基本用法","slug":"基本用法","link":"#基本用法","children":[]},{"level":2,"title":"执行查询","slug":"执行查询","link":"#执行查询","children":[{"level":3,"title":"访问条目类型","slug":"访问条目类型","link":"#访问条目类型","children":[]},{"level":3,"title":"分页记录","slug":"分页记录","link":"#分页记录","children":[]},{"level":3,"title":"搜索记录","slug":"搜索记录","link":"#搜索记录","children":[]}]},{"level":2,"title":"预加载相关记录","slug":"预加载相关记录","link":"#预加载相关记录","children":[]},{"level":2,"title":"统计记录数","slug":"统计记录数","link":"#统计记录数","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/cms/components/collection.md","filePath":"3.x/zh-cn/cms/components/collection.md"}'),u={name:"3.x/zh-cn/cms/components/collection.md"};function r(g,n,k,d,h,m){const t=a("pre-heading"),e=a("post-heading");return o(),c("div",null,[s(t),n[0]||(n[0]=l("h1",null,"集合（Collection）",-1)),s(e),n[1]||(n[1]=i(`<p><code>collection</code> 组件在页面上显示条目集合。集合组件可以在任何页面、布局或部件中使用。</p><h2 id="可用属性"><a href="#可用属性" class="header-anchor">#</a> 可用属性</h2><p>该组件支持以下属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>handle</strong></td><td><a href="./../tailor/blueprints.html">条目蓝图</a>的句柄。</td></tr><tr><td><strong>recordsPerPage</strong></td><td>单页显示的记录数。留空则禁用分页。</td></tr><tr><td><strong>pageNumber</strong></td><td>此值用于确定用户所在的页码。</td></tr><tr><td><strong>sortColumn</strong></td><td>记录排序所依据的列名。</td></tr><tr><td><strong>sortDirection</strong></td><td>记录排序的方向。支持的值为 <code>asc</code> 和 <code>desc</code>。</td></tr></tbody></table></div><h2 id="基本用法"><a href="#基本用法" class="header-anchor">#</a> 基本用法</h2><p>以下示例向页面添加了一个 <strong>Blog\\Post</strong> 条目的集合。在 Twig 中通过循环默认的 <code>collection</code> 变量来访问该集合。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> collection <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>当同一页面上使用多个集合时，可以使用组件别名将组件分配名称 <strong>posts</strong>，这就是页面可用的变量名称。以下集合使用 <code>posts</code> 变量来访问。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token section"><span class="token punctuation">[</span><span class="token section-name selector">collection posts</span><span class="token punctuation">]</span></span>
<span class="token key attr-name">handle</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Blog\\Post</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> post <span class="token operator">in</span> posts <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> post<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div></div><p>使用 <code>is empty</code> 或 <code>is not empty</code> 表达式来检查集合是否至少有一条可显示的记录。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> posts <span class="token operator">is</span> <span class="token operator">not</span> empty <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token comment">{# ... #}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="执行查询"><a href="#执行查询" class="header-anchor">#</a> 执行查询</h2><p>当使用方法访问组件变量时，它将切换到<a href="./../../extend/database/query.html">数据库模型查询</a>。例如，要仅显示字段 <code>color</code> 值为 <strong>blue</strong> 的条目，可以使用 <code>where</code> 查询方法。使用 <code>{% set %}</code> Twig 标签将结果赋值给新变量。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> bluePosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>where<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>color<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>blue<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>要仅显示具有相关作者的文章，可以使用 <code>whereRelation</code> 查询方法。使用 <code>get()</code> 方法完成查询。以下示例列出分配给 slug 设置为 <strong>bella-vista</strong> 的 <code>author</code> 的文章。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> authorPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>whereRelation<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>author<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>slug<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>bella-vista<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="访问条目类型"><a href="#访问条目类型" class="header-anchor">#</a> 访问条目类型</h3><p>要按条目类型筛选记录，使用 <code>content_group</code> 属性执行 <code>where()</code> 查询。以下示例将列出使用条目类型代码 <strong>featured_post</strong> 的文章。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> featuredPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>where<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>content_group<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>featured_post<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="分页记录"><a href="#分页记录" class="header-anchor">#</a> 分页记录</h3><p>您也可以使用 <code>paginate()</code> 方法对集合进行分页。以下示例将文章按每页 <strong>10</strong> 条进行分页并显示分页导航。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> authorPosts <span class="token operator">=</span> posts<span class="token punctuation">.</span>whereRelation<span class="token punctuation">(</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">)</span><span class="token punctuation">.</span>paginate<span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> pager<span class="token punctuation">(</span>authorPosts<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><div class="custom-block tip"><p>请参阅<a href="./../features/pagination.html">分页功能</a>了解更多关于记录分页的信息。</p></div><h3 id="搜索记录"><a href="#搜索记录" class="header-anchor">#</a> 搜索记录</h3><p>要搜索记录，使用 <a href="./../../extend/database/query.html"><code>searchWhere()</code> 方法</a>对列值执行搜索查询。以下示例将使用不区分大小写的查询在提供的搜索词和列中搜索记录。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> foundPages <span class="token operator">=</span> pages<span class="token punctuation">.</span>searchWhere<span class="token punctuation">(</span>searchTerm<span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string"><span class="token punctuation">&#39;</span>title<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>content<span class="token punctuation">&#39;</span></span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>您还可以使用 <a href="./../../extend/database/relations.html"><code>searchWhereRelation()</code> 方法</a>搜索相关记录，其中关系名称包含在方法中用于查询关系是否存在。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> foundPages <span class="token operator">=</span> pages<span class="token punctuation">.</span>searchWhereRelation<span class="token punctuation">(</span>searchTerm<span class="token punctuation">,</span> <span class="token string"><span class="token punctuation">&#39;</span>author<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string"><span class="token punctuation">&#39;</span>title<span class="token punctuation">&#39;</span></span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="预加载相关记录"><a href="#预加载相关记录" class="header-anchor">#</a> 预加载相关记录</h2><p>在某些情况下，出于性能原因，您可能希望预加载相关记录。在集合上使用 <code>load</code> 方法，传入关系名称。在下面的示例中，<code>categories</code> 关系将与集合中的每篇文章一起加载。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">do</span> authorPosts<span class="token punctuation">.</span>load<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>categories<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="统计记录数"><a href="#统计记录数" class="header-anchor">#</a> 统计记录数</h2><p>假设您想显示博客分类列表并统计每个分类中的文章数量。首先，在分类蓝图上定义<a href="./../../element/content/field-entries.html">反向关系</a>为 <strong>posts</strong>。</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">posts</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> entries
    <span class="token key atrule">source</span><span class="token punctuation">:</span> Blog\\Post
    <span class="token key atrule">inverse</span><span class="token punctuation">:</span> categories
    <span class="token key atrule">hidden</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>然后，在集合组件上调用 <code>withCount</code> 函数，接着调用 <code>get</code> 返回分类记录集合。这将在每个分类上创建一个名为 <strong>post_count</strong> 的属性。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> categories <span class="token operator">=</span> collection<span class="token punctuation">.</span>withCount<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>posts<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">.</span>get<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">for</span> category <span class="token operator">in</span> categories <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h5</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> category<span class="token punctuation">.</span>title <span class="token delimiter punctuation">}}</span></span> (<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> category<span class="token punctuation">.</span>post_count <span class="token delimiter punctuation">}}</span></span> posts)<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h5</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endfor</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../features/pagination.html">分页</a></li><li><a href="./../../extend/database/model.html">模型查询</a></li><li><a href="./../../extend/database/relations.html">数据库关系</a></li></ul></div>`,38))])}const f=p(u,[["render",r]]);export{v as __pageData,f as default};
